SELECT sscl.LEDGER_ID AS ledgerId, DATE_FORMAT(sscl.CONTRACT_END_DATE, '%Y-%m') AS expirationMonth, sscl.PROJECT_NAME AS projectName, sscdp.NUM AS num, sscl.CONTRACT_START_DATE AS contractStartDate, sscl.CONTRACT_END_DATE AS contractEndDate, sscl.DELAY_REASON AS delayReason, sscl.NEXT_SUGGEST AS nextSuggest, sscl.HEAD_PERSON AS headPerson, sscl.PROJECT_TOTAL_MONEY AS projectTotalMoney, sscl.ADD_NUM AS addNum, sscl.ADD_BEFORE_MONEY AS addBeforeMoney, sscl.ADD_AFTER_MONEY AS addAfterMoney, sscl.ADD_DECREMENT_MONEY AS addDecrementMoney, sscl.ADD_DECREMENT_RATIO AS addDecrementRatio, sscl.ABO_BEFORE_MONEY AS aboBeforeMoney, sscl.ABO_AFTER_MONEY AS aboAfterMoney, sscl.ABO_DECREMENT_MONEY AS aboDecrementMoney, sscl.ABO_DECREMENT_MONEY AS aboDecrementRatio, sscl.LAST_UPDATE_DATE AS lastUpdateDate, sscl.DATA_SOURCE AS dataSource FROM scc_sou_ch_ledger sscl LEFT JOIN scc_sou_ch_design_plan sscdp ON sscdp.PROJECT_ID = sscl.LEDGER_ID
AND DATE_FORMAT(sscl.CONTRACT_END_DATE, '%Y-%m') = #{obj.expirationMonth,jdbcType=VARCHAR}
AND sscl.PROJECT_NAME = #{obj.projectName,jdbcType=VARCHAR}
AND sscdp.NUM = #{obj.num,jdbcType=INTEGER}
AND sscl.LEDGER_ID = #{obj.ledgerId}
AND sscl.HEAD_PERSON LIKE CONCAT('%', #{obj.headPerson,jdbcType=VARCHAR}, '%')
AND sscl.CONTRACT_START_DATE >= #{obj.contractStartDate,jdbcType=TIMESTAMP}
AND sscl.CONTRACT_END_DATE <= #{obj.contractEndDate,jdbcType=TIMESTAMP}
AND sscl.PROJECT_TOTAL_MONEY >= #{obj.projectTotalMoney,jdbcType=DECIMAL}
AND sscl.PROJECT_TOTAL_MONEY <= #{obj.projectTotalMoneyEnd,jdbcType=DECIMAL}
AND sscl.DATA_SOURCE = #{obj.dataSource,jdbcType=VARCHAR}

SELECT
DATE_FORMAT(sscl.CONTRACT_END_DATE, '%Y-%m') AS expirationMonth,
sscl.LEDGER_ID AS ledgerId,
sscl.PROJECT_NAME AS projectName,
sscdp.NUM as num,
sscdp.STATUS as mainPlanStatus,
sscl.CONTRACT_START_DATE AS contractStartDate,
sscl.CONTRACT_END_DATE AS contractEndDate,
sscl.DELAY_REASON AS delayReason,
sscl.HEAD_PERSON AS headPerson,
sscl.PROJECT_TOTAL_MONEY AS projectTotalMoney
FROM
scc_sou_ch_ledger sscl
LEFT JOIN scc_sou_ch_design_plan sscdp ON sscdp.PROJECT_ID = sscl.LEDGER_ID


        AND DATE_FORMAT(sscl.CONTRACT_END_DATE, '%Y-%m') = #{obj.expirationMonth,jdbcType=VARCHAR}


        AND sscl.PROJECT_NAME = #{obj.projectName,jdbcType=VARCHAR}


        AND sscl.HEAD_PERSON LIKE CONCAT('%', #{obj.headPerson,jdbcType=VARCHAR}, '%')


        AND sscdp.NUM >= #{obj.num,jdbcType=INTEGER}


        AND sscdp.NUM <= #{obj.endNum,jdbcType=INTEGER}


        AND sscl.CONTRACT_START_DATE >= #{obj.contractStartDate,jdbcType=TIMESTAMP}


        AND sscl.CONTRACT_END_DATE <= #{obj.contractEndDate,jdbcType=TIMESTAMP}


        AND sscl.PROJECT_TOTAL_MONEY >= #{obj.projectTotalMoney,jdbcType=DECIMAL}


        AND sscl.PROJECT_TOTAL_MONEY <= #{obj.projectTotalMoneyEnd,jdbcType=DECIMAL}
